-- Let's trace the relationship: account -> profile -> sessionbehavior -> contentbehavior -> moderationaction -> securitydetection
SELECT COUNT(*) FROM moderationaction ma 
JOIN securitydetection sd ON ma.masedetref = sd.secdetkey;

-- Check what scores are available in moderationaction
SELECT modactkey, netinflscore, coordscore, authenscore, credscore, reputscore, trustval, impactval
FROM moderationaction LIMIT 5;
